// foreignJurisdictionResponse is the wire shape every handler returns when the
// caller's request targets a resource in a foreign jurisdiction. The SPA
// recognises `error: "foreign_jurisdiction"` and renders a friendly card with
// the supplied console_url.
type foreignJurisdictionResponse struct {
	Error        string `json:"error"`        // always "foreign_jurisdiction"
	Jurisdiction string `json:"jurisdiction"` // resource's home jurisdiction (e.g. "us")
	ConsoleURL   string `json:"console_url"`  // deep link into the home console; relative if base unknown
	Message      string `json:"message"`      // human-readable copy
}

// buildForeignJurisdictionResponse constructs the wire payload. Shared by the
// 409 helper and by handleMe, which embeds the same shape under
// regional_unavailable on a 200 response.
func (s *Server) buildForeignJurisdictionResponse(ctx context.Context,
	jurisdiction, returnPath, resourceLabel string) foreignJurisdictionResponse {
	base := s.jurisdictionHosts[jurisdiction]
	consoleURL := returnPath
	hostLabel := ""
	if base == "" {
		slogutil.Warn(ctx, "jurisdiction host map missing entry",
			slog.String("jurisdiction", jurisdiction))
	} else {
		consoleURL = strings.TrimRight(base, "/") + returnPath
		u, err := neturl.Parse(base)
		if err != nil {
			slogutil.Warn(ctx, "jurisdiction host failed to parse",
				slog.String("jurisdiction", jurisdiction),
				slog.String("base", base),
				slog.String("error", err.Error()))
		} else {
			hostLabel = u.Host
		}
	}
	message := fmt.Sprintf("%s is hosted in the %s jurisdiction.", resourceLabel, jurisdiction)
	if hostLabel != "" {
		message += fmt.Sprintf(" Open it on %s.", hostLabel)
	}
	return foreignJurisdictionResponse{
		Error:        "foreign_jurisdiction",
		Jurisdiction: jurisdiction,
		ConsoleURL:   consoleURL,
		Message:      message,
	}
}

// writeForeignJurisdiction emits a 409 with the structured shape. returnPath
// is the in-home-console path the user should land on; resourceLabel is the
// short noun phrase used in the message.
func (s *Server) writeForeignJurisdiction(w http.ResponseWriter, r *http.Request,
	jurisdiction, returnPath, resourceLabel string) {
	writeJSON(w, http.StatusConflict,
		s.buildForeignJurisdictionResponse(r.Context(), jurisdiction, returnPath, resourceLabel))
}

// wrongJurisdictionResponse is the CLI device-flow 409 wire shape. Distinct
// from foreignJurisdictionResponse because CLIs need a device-auth URL they
// can poll, not a console deep-link.
type wrongJurisdictionResponse struct {
	Error            string `json:"error"` // always "wrong_jurisdiction"
	HomeJurisdiction string `json:"home_jurisdiction"`
	DeviceAuthURL    string `json:"device_auth_url"`
	Message          string `json:"message"`
}

// writeWrongJurisdiction emits the CLI device-flow 409 telling the caller to
// retry against their home jurisdiction.
func (s *Server) writeWrongJurisdiction(ctx context.Context, w http.ResponseWriter, homeJurisdiction, providerID string) {
	// /api/auth/<provider>/device is an auth-host endpoint.
	base := s.jurisdictionAuthHosts[homeJurisdiction]
	if base == "" {
		slogutil.Warn(ctx, "jurisdiction host map missing entry",
			slog.String("jurisdiction", homeJurisdiction))
	}
	deviceURL := ""
	if base != "" && providerID != "" {
		deviceURL = strings.TrimRight(base, "/") + "/api/auth/" + providerID + "/device"
	}
	writeJSON(w, http.StatusConflict, wrongJurisdictionResponse{
		Error:            "wrong_jurisdiction",
		HomeJurisdiction: homeJurisdiction,
		DeviceAuthURL:    deviceURL,
		Message:          fmt.Sprintf("This account is homed in %s. Restart the device flow against that jurisdiction.", homeJurisdiction),
	})
}

