package cli

import (
	"errors"
	"fmt"
	"net/url"
	"os"
	"strings"

	"github.com/spf13/cobra"

	"entire.io/core/api"
)

// wrapCrossRegionGuidance recursively wraps each command's RunE so an
// unauthorized failure caused by cross-region targeting gets actionable
// guidance appended. A no-op for any non-401 error, so it's safe to apply
// across the whole command tree (non-HTTP commands never produce one).
func wrapCrossRegionGuidance(cfg Config, cmd *cobra.Command) {
	for _, c := range cmd.Commands() {
		wrapCrossRegionGuidance(cfg, c)
		if c.RunE == nil {
			continue
		}
		inner := c.RunE
		c.RunE = func(cmd *cobra.Command, args []string) error {
			return annotateCrossRegion401(cfg, inner(cmd, args))
		}
	}
}

// annotateCrossRegion401 enriches an HTTP 401 when the command targeted a
// core in a different region than the caller's login. The usual cause is
// pointing --base-url / --context at a foreign cell for a global admin
// read (e.g. `mirrors list`, `users list`): the target core rejects the
// token because it only verifies tokens minted by its own region. The raw
// 401 ("invalid token") gives no clue, so we append what to do instead.
func annotateCrossRegion401(cfg Config, err error) error {
	if err == nil {
		return nil
	}
	var he *api.HTTPError
	if !errors.As(err, &he) || he.Status != 401 {
		return err
	}
	home := loginHomeHost(cfg)
	target := coreHost(resolveBaseURL(cfg))
	if home == "" || target == "" || strings.EqualFold(home, target) {
		return err
	}
	return fmt.Errorf("%w\n\n"+
		"hint: this core (%s) is in a different region than your login (%s); it only\n"+
		"accepts tokens minted by its own region. Most admin reads (e.g. `mirrors\n"+
		"list`, `users list`) are global — run them against your home core without\n"+
		"--base-url/--context; for a region-local operation, log in to %s first",
		err, target, home, target)
}

// loginHomeHost is the host of the core that minted the caller's login
// token. Empty when ENTIRE_TOKEN is in use (the operator is managing their
// own targeting) or no context resolves — in either case we skip the hint.
func loginHomeHost(cfg Config) string {
	if os.Getenv("ENTIRE_TOKEN") != "" {
		return ""
	}
	c, err := currentContext(cfg)
	if err != nil || c == nil {
		return ""
	}
	return coreHost(c.CoreURL)
}

// coreHost returns the lowercase hostname (no port) of a core URL, or ""
// if raw doesn't parse — host-only so a stray :443 can't cause a false
// cross-region verdict.
func coreHost(raw string) string {
	u, err := url.Parse(raw)
	if err != nil {
