package oidcop

import (
	"context"
	"errors"
	"fmt"
	"time"

	"slices"

	"github.com/entirehq/entiredb/modules/jwtverify"
	jose "github.com/go-jose/go-jose/v4"
	josejwt "github.com/go-jose/go-jose/v4/jwt"
	"github.com/zitadel/oidc/v3/pkg/oidc"
	"github.com/zitadel/oidc/v3/pkg/op"

	"entire.io/core/authn"
	"entire.io/core/oidcfed"
)

// Compile-time assertion: Storage implements
// op.TokenExchangeTokensVerifierStorage so pkg/op falls through to our
// VerifyExchangeSubjectToken when its built-in verifier rejects the
// subject_token (typically because the iss is a third-party IdP, not us).
var _ op.TokenExchangeTokensVerifierStorage = (*Storage)(nil)

// oidcFedVerifierCacheTTL is how long a per-provider JWKS cache survives
// before re-fetching. Five minutes mirrors the rest of entire-core's
// JWKS verifier cache and stays well within every federated IdP's
// rotation window (GitHub Actions rotates ~hourly).
const oidcFedVerifierCacheTTL = 5 * time.Minute

// cachedFedVerifier holds the JWKS verifier for one provider plus the
// inputs that produced it; when those change (manifest edit pointing
// the IdP at a new endpoint), the verifier is rebuilt.
type cachedFedVerifier struct {
	jwksURL   string
	issuerURL string
	verifier  *jwtverify.Verifier
}

// VerifyExchangeSubjectToken verifies a subject_token whose iss is a
// registered federated OIDC issuer (e.g. GitHub Actions). pkg/op only
// calls this after its own verifier path failed — own-issuer JWTs are
// handled by the standard access-token verifier wired into the
// Provider's options.
//
// Returns the raw verified claims so ValidateTokenExchangeRequest can
// run the binding's attribute filter against them.
func (s *Storage) VerifyExchangeSubjectToken(ctx context.Context, token string, tokenType oidc.TokenType) (tokenIDOrToken, subject string, claims map[string]any, err error) {
	if tokenType != "" && tokenType != oidc.JWTTokenType && tokenType != oidc.AccessTokenType {
		return "", "", nil, fmt.Errorf("oidcop: unsupported subject_token_type %q for federated exchange", tokenType)
	}

	iss, err := unverifiedIssuer(token)
	if err != nil {
		return "", "", nil, fmt.Errorf("read subject_token iss: %w", err)
	}
	if iss == "" {
		return "", "", nil, errors.New("subject_token missing iss claim")
	}

	// Sibling-region branch: the subject_token is a login JWT issued by
	// another regional core in our federation. We verify it against that
	// sibling's published JWKS (COR-382 — no shared keystore); trust is
	// anchored by iss naming a configured sibling. The validator
	// (validateForeignSessionExchange) checks the substantive claims.
	if s.siblingVerifiers != nil && s.siblingVerifiers.IsTrusted(iss) {
		rawClaims, err := authn.VerifyRawClaims(ctx, s.siblingVerifiers, token)
		if err != nil {
			return "", "", nil, fmt.Errorf("verify sibling subject_token: %w", err)
		}
		return token, stringClaim(rawClaims, "sub"), rawClaims, nil
	}

	if s.oidcfedSvc == nil {
		return "", "", nil, errors.New("oidcop: federated subject_token verification not configured")
	}
	provider, err := s.oidcfedSvc.GetProviderByIssuer(ctx, iss)
	if err != nil {
		if errors.Is(err, oidcfed.ErrProviderNotFound) {
			return "", "", nil, fmt.Errorf("subject_token issuer not registered: %s", iss)
		}
		return "", "", nil, fmt.Errorf("lookup provider by issuer: %w", err)
	}

	verifier := s.fedVerifierFor(provider)
	rawClaims, err := authn.VerifyRawClaims(ctx, verifier, token)
	if err != nil {
		return "", "", nil, fmt.Errorf("verify federated subject_token: %w", err)
	}
	// pkg/op surfaces these via req.GetExchangeSubject /
	// GetExchangeSubjectTokenClaims so the validator can match
	// AttributeFilter, stamp `act`, and override the issued JWT's
	// subject via req.SetSubject(saAccountID) after authz passes.
	return token, stringClaim(rawClaims, "sub"), rawClaims, nil
}

// VerifyExchangeActorToken verifies the RFC 8693 actor_token presented
// on an on-behalf-of token exchange. Only own-issuer (entire-core)
// actor_tokens are accepted — federated/cross-juris actor delegation
// has no consumer today, and pkg/op routes every actor_token through
// this hook (no built-in fallthrough as it has for own-issuer subject_
// tokens).
//
// On success returns the actor's verified `sub`, our issuer URL, the
// raw claims map (for downstream act stamping), and a nil error. The
// caller is the ValidateTokenExchangeRequest dispatch — it consults the
// returned claims to decide whether the actor is authorised to act on
// behalf of the subject for the requested audience.

		return oidc.ErrAccessDenied().WithDescription("session liveness check failed; please re-login")
	}
	if !alive {
		return oidc.ErrAccessDenied().WithDescription("session has been revoked; please re-login")
	}
	return nil
}

// validateForeignSessionExchange gates the cross-juris exchange. The
// subject_token is a sibling region's login JWT. Trust anchor is the
// configured sibling allow-list (siblingVerifiers) — see ADR 20260520.
// The verifier has already confirmed signature; this hook checks the
// substantive claims:
//
//   - subject_token must be a session credential (ScopeEntireSession). For
//     the AuthBaseURL (session-widening) target it must additionally be a real
//     login JWT (aud == iss). The jurisdiction (identity) target accepts any
//     session credential — including a resource-audienced one such as
//     entire-mcp's connector token — since it narrows to openid regardless.
//   - audience must be the local AuthBaseURL (→ a local-audience login
//     JWT wrapping the foreign identity) or the local jurisdiction
//     audience (→ an identity access token; ADR 20260612). Both are
//     identity-bearing credentials gated solely by home-region liveness;
//     no local SpiceDB or cluster binding is involved, which is why a
//     sibling may mint them directly. Sibling JWTs still cannot mint
//     repo/ops/etc credentials directly — those need a local authz check,
//     so the caller foreign-sessions first, then re-exchanges at the new
//     home. The direct identity path grants nothing the two-hop route
//     couldn't (a foreign-session login JWT carries the full exchange
//     set); it only saves a round trip.
//   - subject_token must not itself carry foreign_iss — no chained
//     cross-juris hops. Each cross-juris act starts from a native login
//     JWT, so the audit trail names exactly one foreign issuer.
//
// SetCurrentScopes shapes the issued token by target: the AuthBaseURL
// target mirrors the subject's scope (same exchange capabilities at the
// new home), the jurisdiction target narrows to scope=openid (identity
// only). The claim hook adds foreign_iss either way.
//
// After the claim-shape checks, we confirm the subject is still active
// at its home issuer. Without this, a sibling-issued login JWT minted
// before a suspend keeps minting foreign-session tokens at every peer
// for the full login-JWT TTL (authn.LoginTokenTTL) — the local
// handle-state middleware cache can't gate the foreign principal
// because it's keyed by local sessions. The check itself runs locally
// (LocalIssuerIntrospector): accounts/handles are global tables, so
// the home region's answer is a follower read away. issuerIntrospect
// being nil is interpreted as "no introspection wired" (test/dev) and
// the exchange falls through to claim-shape-only — production wiring
// always sets it.
func (s *Storage) validateForeignSessionExchange(ctx context.Context, req op.TokenExchangeRequest, subjectClaims map[string]any, subjectIss, target string, subjectScopes []authn.Scope) error {
	identityTarget := s.isJurisdictionAudience(target)
	if target != s.loginAud && !identityTarget {
		return oidc.ErrInvalidTarget().WithDescription(
			"cross-juris subject_token may exchange only for this core's AuthBaseURL or its jurisdiction audience; re-exchange at the new home for repo/ops credentials")
	}
	if !authn.HasScope(subjectScopes, authn.ScopeEntireSession) {
		return oidc.ErrInvalidGrant().WithDescription("subject_token is not a session credential (missing entire:session)")
	}
	if fi := stringClaim(subjectClaims, "foreign_iss"); fi != "" {
		return oidc.ErrInvalidGrant().WithDescription("subject_token already carries foreign_iss; chained cross-juris exchange is not permitted")
	}
	// The self-audienced login-JWT shape (aud == iss) is required only for
	// session widening (the loginAud target): that mints a full local session,
	// so the input must be a genuine browser login JWT, not a token some other
	// resource was audienced to. The identity narrowing (jurisdiction audience)
	// emits an openid-only token authorized live downstream, so any session
	// credential is a valid input — including entire-mcp's connector token,
	// which carries entire:session but is RFC 8707 resource-audienced to the MCP
	// (aud = <mcp-resource>, not iss). The entire:session check above already
	// excludes narrowed api-access/ops/repo tokens (they don't carry it), so the
	// aud check adds nothing on the identity path — see the local analogue,
	// validateIdentityExchange.
	if !identityTarget && !subjectAudienceMatchesIssuer(subjectClaims, subjectIss) {
		return oidc.ErrInvalidGrant().WithDescription("subject_token is not a sibling login JWT (aud does not equal iss)")
	}
	if s.issuerIntrospect != nil {
		status, err := s.issuerIntrospect.Introspect(ctx, subjectIss, req.GetSubject(), subjectClaims)
		switch {
		case err != nil:
			return oidc.ErrAccessDenied().WithDescription("issuer introspection failed; please retry")
		case status == SubjectActive:
			// Fall through and mint.
		case status == SubjectPendingDeletion && !identityTarget:
			// COR-1027: allow session widening so a cross-cell account can reach
			// the home-gated cancel endpoint. Safe only here — the widened
			// session is confined by deletionPendingAllowedPath at the home cell
			// and can't be re-exchanged (a local re-exchange hits
			// assertNotPendingDeletion). The identity target stays refused.
		default:
			// SubjectInactive, or pending-deletion reaching for the identity target.
			return oidc.ErrAccessDenied().WithDescription("home region reports subject is no longer active")
		}
	}
	if identityTarget {
		// Narrow to an identity access token: identity only, authorized
		// live at the read services. Same shape as the local identity
		// exchange (validateIdentityExchange), reached cross-juris.
		req.SetCurrentScopes([]string{string(authn.ScopeOpenID)})
		return nil
	}
	req.SetCurrentScopes(scopeStringsFromClaims(subjectScopes))
	return nil
}

// exchangeAudienceSkipsCnf reports whether the exchange targets a public
// bearer surface where no receiver verifies cnf — the core/AS audience
// (api-access, sa-session; core /api/v1, entire.io) or the jurisdiction
// audience (the identity access token's internal read services, which
// verify JWKS only). Stamping cnf for either would assert a binding no
// receiver checks. ValidateTokenExchangeRequest has already enforced a
// single audience by the time claims are stamped.
func (s *Storage) exchangeAudienceSkipsCnf(req op.TokenExchangeRequest) bool {
	auds := req.GetAudience()
	if len(auds) != 1 {
		return false
